def compute_covariance(x, y):
    n = len(x)
    mean_x, mean_y = sum(x)/n, sum(y)/n
    return sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n)) / (n - 1)
print(compute_covariance([1, 2, 3], [4, 5, 6]))

