def rank_transform(arr, method='average'):
    # arr: list of numbers
    sorted_idx = sorted(range(len(arr)), key=lambda i: arr[i])
    ranks = [0]*len(arr)
    i = 0
    while i < len(arr):
        # find all equal values
        j = i
        while j+1 < len(arr) and arr[sorted_idx[j]] == arr[sorted_idx[j+1]]:
            j += 1
        # compute rank for ties
        if method == 'average':
            rank_val = (i+1 + j+1)/2.0
        elif method == 'min':
            rank_val = i+1
        else:
            rank_val = j+1
        for k in range(i, j+1):
            ranks[sorted_idx[k]] = rank_val
        i = j+1
    return ranks
# Example
print(rank_transform([85,92,78,92,70]))  # [3.0, 4.5, 2.0, 4.5, 1.0]

