import pandas as pd
def add_lags(df, col, lags):
    for l in range(1, lags + 1):
        df[f'{col}_lag_{l}'] = df[col].shift(l)
    return df.dropna()
df = pd.DataFrame({'val': [10, 20, 30, 40, 50]})
print(add_lags(df, 'val', 2))

import statsmodels.api as sm
import pandas as pd

def get_best_next_feature(X, y, current_features):
    best_rss = float('inf')
    best_feat = None
    for col in X.columns:
        if col not in current_features:
            feats = current_features + [col]
            model = sm.OLS(y, sm.add_constant(X[feats])).fit()
            if model.ssr < best_rss:
                best_rss = model.ssr
                best_feat = col
    return best_feat
